    offboard.set_position_velocity_acceleration_ned({NAN,NAN,NAN,NAN},{telemetry.velocity_ned().north_m_s,telemetry.velocity_ned().east_m_s,telemetry.velocity_ned().down_m_s,telemetry.attitude_angular_velocity_body().yaw_rad_s},{0,0,0});

    Offboard::Result offboard_result = offboard.start();
    if (offboard_result != Offboard::Result::Success) {
        std::cerr << "Offboard start failed: " << offboard_result << '\n';
        return false;
    }

    std::cout << "Offboard started\n";

    Offboard::AccelerationNed acNed;
    acNed.north_m_s2 = 5;
    acNed.down_m_s2 = -0.1;
    acNed.east_m_s2 = 0;

    //offboard.set_acceleration_ned(acNed);
    offboard.set_position_velocity_acceleration_ned({NAN,NAN,NAN,NAN},{NAN,NAN,NAN,NAN},acNed);`


However the set_position_velocity_acceleration_ned works the same as if I had set the velocity to the same values as the acceleration.
It is the same with set_acceleration_ned. Does anyone know why?


Using "make px4_sitl_sih sihsim_quadx"
